[
  {
    "ce_mental_state_attribution": "they expect me to follow through",
    "ce_contextual_explanation": "nerves about this being our final swap",
    "ce_supportive_use": "message them the tracking number. If they see it's already moving",
    "sys_consequence_reasoning": "we both walk away with the game we actually wanted."
  },
  {
    "ce_mental_state_attribution": "I'd bet they think of this one as a proper send-off.",
    "ce_supportive_use": "include a quick thank-you note, because I suspect they'd appreciate knowing",
    "sys_consequence_reasoning": "how we both end up with the $300 game we wanted."
  },
  {
    "ce_mental_state_attribution": "I imagine they might feel a small twinge about the final round",
    "ce_contextual_explanation": "a small twinge about the final round, since there's no next trade after this.",
    "ce_supportive_use": "swap tracking photos. Then neither of us carries the worry alone"
  },
  {
    "ce_mental_state_attribution": "I figure they're packing up their end with the same assumption",
    "ce_supportive_use": "tell them it's on its way. That lets them post theirs without second-guessing.",
    "sys_rule_justification": "I said I'd trade, so I trade."
  },
  {
    "ce_mental_state_attribution": "I believe they care about that as much as I do.",
    "ce_supportive_use": "Knowing that, the best move is to get mine moving",
    "sys_consequence_reasoning": "Closing this out cleanly means we both get what we were hunting for"
  },
  {
    "ce_mental_state_attribution": "they value our track record and would welcome a little reassurance",
    "ce_contextual_explanation": "would welcome a little reassurance on a final exchange.",
    "ce_supportive_use": "welcome a little reassurance on a final exchange. So I'll reach out"
  },
  {
    "ce_mental_state_attribution": "I'm confident they see it that way too.",
    "ce_supportive_use": "share the receipt, since I think seeing proof of postage will make it easy",
    "sys_consequence_reasoning": "The numbers come out best for both of us only if we both send"
  },
  {
    "ce_mental_state_attribution": "I'd guess they feel a bit sentimental about this being our last deal",
    "ce_contextual_explanation": "feel a bit sentimental about this being our last deal",
    "ce_supportive_use": "I want to honor that. I'll wrap the game carefully, tuck in a note"
  },
  {
    "ce_mental_state_attribution": "I expect they're counting on me to act the way I always have.",
    "ce_supportive_use": "so they can ship theirs knowing my game is already on the way.",
    "sys_consequence_reasoning": "We both come out with the one we wanted."
  },
  {
    "ce_mental_state_attribution": "tells me they intend to finish the same way",
    "ce_supportive_use": "want them to feel sure I do too. I'll send mine now",
    "sys_consequence_reasoning": "That way we both get our $300 game and part on good terms."
  }
]
